export type AnomalyKind =
  | 'second-moon'
  | 'red-moon'
  | 'forest-watcher'
  | 'observatory-signal'
  | 'meteor'
  | 'lights-out';

export interface AnomalyVisual {
  type: AnomalyKind;
  active: boolean;
  opacity: number;
  startedAt: number;
  duration: number;
}

