  constructor(canvas: HTMLCanvasElement, style: RenderStyle = 'painterly') {
    this._canvas = canvas;
    this._style = style;
    this._ctx = canvas.getContext('2d', { alpha: false })!;
    this._outCtx = this._ctx;
    this._buildFeatures();
    this._buildPaper();
    this._bindPointer();
  }
  getStyle(): RenderStyle {
    return this._style;
  }

  /** Set once by the engine at startup, when the absence was long enough. */
  private _returnSummary: string[] | null = null;

  /**
   * Supplies the "while you were away" lines, shown once on the terminal and
   * then released. The engine owns whether there is a gap worth reporting.
   */
  setReturnSummary(lines: string[] | null): void {
    this._returnSummary = lines;
  }

  /** Feeds the observatory terminal its readout. The engine owns this state; the
   *  renderer just displays it, so the terminal never reaches into the journal
   *  or secret systems itself. */
  setTerminalTelemetry(observations: number, secrets: number): void {
    this._telemetry.observations = observations;
    this._telemetry.secrets = secrets;
  }

  /** Short code the terminal identifies the current site by. */
  private _siteCode(): string {
    const words = this._world.name.replace(/^(the|a|an)\s+/i, '').split(/\s+/);
    const letters = words.map((w) => w.replace(/[^a-z0-9]/gi, '')[0] ?? '').join('');
    return (letters || 'site').toUpperCase().slice(0, 5).padEnd(3, 'x');
  }

/**
 * Fallback used when the host has not reported a monitor layout.
 *
 * This has to track the canvas rather than being a fixed size: a hardcoded
 * 1920x1080 meant a 1280x720 canvas composed a 1920-wide scene and squashed it
 * on the way out, which pushed the corridor's vanishing point off centre and
 * skewed the whole image.
 */
  private _fallbackViewport(): MonitorViewport {
  const dpr = this._dpr || 1;
  return {
    index: 0,
    x: 0,
    y: 0,
    w: Math.max(1, this._canvas.width / dpr),
    h: Math.max(1, this._canvas.height / dpr),
  };
}
  private _drawTerminal(grade: SkyGrade, hour: number, dt: number): void {
    // The terminal takes the context per call rather than holding one. The
    // offscreen buffer is reallocated on resize and on a monitor-layout change,
    // and a retained context would then point at an orphaned canvas ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â the
    // terminal would silently stop drawing, which is exactly what happened when
    // per-monitor support landed.
    this._crt ??= new CrtTerminal(this._seed);
    if (this._startedAt === 0) this._startedAt = performance.now();

    const hh = String(Math.floor(hour)).padStart(2, '0');
    const mm = String(Math.floor((hour % 1) * 60)).padStart(2, '0');
    const anomaly = this._anomalies.find((a) => a.active);

    this._crt.render(
      this._ctx, this._w, this._h, grade,
      {
        worldName: this._world.name,
        worldCode: this._siteCode(),
        biome: this._world.biome,
        clock: `${hh}:${mm}`,
        weather: this._weather.condition.toUpperCase(),
        observations: this._telemetry.observations,
        secrets: this._telemetry.secrets,
        anomalyActive: !!anomaly,
        anomalyName: anomaly?.type,
        uptime: (performance.now() - this._startedAt) / 1000,
        returnSummary: this._returnSummary ?? undefined,
      },
      dt
    );
  }

  private _buildPaper(): void {
    const size = 512;
    const c = document.createElement('canvas');
    c.width = size;
    c.height = size;
    const g = c.getContext('2d')!;
    const rnd = mulberry32(4242);

    g.fillStyle = '#f2ece0';
    g.fillRect(0, 0, size, size);

    for (let i = 0; i < 9000; i++) {
      const x = rnd() * size;
      const y = rnd() * size;
      const v = rnd();
      g.fillStyle = v > 0.5 ? 'rgba(120,108,92,0.05)' : 'rgba(255,252,244,0.07)';
      g.fillRect(x, y, 1 + rnd() * 2, 1 + rnd() * 2);
    }

    for (let i = 0; i < 220; i++) {
      const x = rnd() * size;
      const y = rnd() * size;
      g.strokeStyle = 'rgba(150,138,118,0.035)';
      g.lineWidth = 0.7;
      g.beginPath();
      g.moveTo(x, y);
      g.lineTo(x + (rnd() - 0.5) * 90, y + (rnd() - 0.5) * 90);
      g.stroke();
    }

    this._inks = c;
  }


